VALUES
 ('cadastros.produtos.importar.arquivo','/dashboard/cadastros/produtos/importar','Migrar estoque','Subir planilha','Selecione o arquivo .xlsx baixado como planilha padrão e já preenchido com seu estoque.','O sistema lê a aba de estoque e monta a prévia; nada é gravado antes de você conferir.','MODELO_migracao_estoque_PS.xlsx','Subir uma planilha fora do padrão — o cabeçalho precisa ter as colunas "codigo" e "nome" (linha 4 do modelo).','gestao_empresarial',10,'publicado'),
 ('cadastros.produtos.importar.ind_itens','/dashboard/cadastros/produtos/importar','Migrar estoque','Itens','Quantidade de linhas de produto lidas da planilha (fora a linha de exemplo).','Confirma que o arquivo foi lido por inteiro antes de carregar.','128','Esquecer linhas em branco no meio da planilha — elas são ignoradas na contagem.','gestao_empresarial',20,'publicado'),
 ('cadastros.produtos.importar.ind_qtd_liquida','/dashboard/cadastros/produtos/importar','Migrar estoque','Quantidade líquida','Soma das quantidades em estoque de todas as linhas (positivas e negativas).','Dá uma visão geral do volume que será lançado no saldo.','4.530','Confundir com número de itens — aqui é a soma das quantidades, não a contagem de produtos.','gestao_empresarial',30,'publicado'),
 ('cadastros.produtos.importar.ind_positivos','/dashboard/cadastros/produtos/importar','Migrar estoque','Com saldo positivo','Quantos produtos têm quantidade em estoque maior que zero.','Mostra quantos itens já entram com saldo.','95','—','gestao_empresarial',40,'publicado'),
 ('cadastros.produtos.importar.ind_zerados','/dashboard/cadastros/produtos/importar','Migrar estoque','Zerados/vazios','Quantos produtos entram com quantidade zero.','Ajuda a ver quantos itens ficam cadastrados sem saldo inicial.','20','Deixar a coluna de quantidade vazia por engano — vazio conta como linha com erro (falta quantidade).','gestao_empresarial',50,'publicado'),
 ('cadastros.produtos.importar.ind_negativos','/dashboard/cadastros/produtos/importar','Migrar estoque','Negativos','Quantos produtos têm quantidade negativa.','Saldos negativos são aceitos na migração; o indicador alerta para você revisar se é esperado.','3','Importar negativo sem querer — revise antes de carregar.','gestao_empresarial',60,'publicado'),
 ('cadastros.produtos.importar.ind_soma_custo','/dashboard/cadastros/produtos/importar','Migrar estoque','Soma dos custos','Soma do custo médio informado em todas as linhas.','Confere a ordem de grandeza dos custos antes de gravar.','R$ 12.340,00','Usar vírgula/ponto trocados na planilha — confira se o valor bate com o esperado.','gestao_empresarial',70,'publicado'),
 ('cadastros.produtos.importar.ind_valor_liquido','/dashboard/cadastros/produtos/importar','Migrar estoque','Valor do estoque líquido','Soma de quantidade × custo médio de cada linha.','Estima o valor financeiro do estoque que será migrado.','R$ 87.900,00','—','gestao_empresarial',80,'publicado'),
 ('cadastros.produtos.importar.ind_repetidos','/dashboard/cadastros/produtos/importar','Migrar estoque','Códigos repetidos','Quantos códigos aparecem mais de uma vez no arquivo.','Códigos repetidos são recusados (erro) para não sobrescrever saldo; precisam ser corrigidos na planilha.','0','Deixar o mesmo código em duas linhas — a segunda vira erro e não é gravada.','gestao_empresarial',90,'publicado'),
 ('cadastros.produtos.importar.so_validas','/dashboard/cadastros/produtos/importar','Migrar estoque','Carregar só as válidas','Marque para carregar apenas as linhas ok e com aviso, ignorando as de erro.','Permite migrar o que está correto sem travar por causa de poucas linhas com erro.','—','Esquecer de corrigir depois as linhas que ficaram de fora — elas não entram enquanto o erro existir.','gestao_empresarial',100,'publicado'),
 ('cadastros.produtos.importar.col_status','/dashboard/cadastros/produtos/importar','Migrar estoque','Status','Resultado da conferência da linha: 🟢 ok, 🟡 aviso (carrega) ou 🔴 erro (fica de fora).','Diz, linha a linha, o que entra e o que precisa de correção.','🟢','Ignorar as linhas 🔴 — elas não são gravadas.','gestao_empresarial',110,'publicado'),
 ('cadastros.produtos.importar.col_codigo','/dashboard/cadastros/produtos/importar','Migrar estoque','Código','O código interno do produto, lido da planilha.','É a chave do produto; reimportar o mesmo código não duplica, apenas ajusta o saldo.','PROD-001','Código em branco — a linha vira erro.','gestao_empresarial',120,'publicado'),
 ('cadastros.produtos.importar.col_descricao','/dashboard/cadastros/produtos/importar','Migrar estoque','Descrição','O nome/descrição do produto.','Identifica o produto no cadastro e nas listas.','Parafuso sextavado 1/2"','Descrição em branco — a linha vira erro.','gestao_empresarial',130,'publicado'),
 ('cadastros.produtos.importar.col_qtd','/dashboard/cadastros/produtos/importar','Migrar estoque','Qtd','A quantidade em estoque informada para o produto (aceita negativo).','Vira o saldo-alvo: o ajuste gera uma única movimentação de inventário para chegar nesse valor.','120','Deixar vazio — sem quantidade a linha vira erro.','gestao_empresarial',140,'publicado'),
 ('cadastros.produtos.importar.col_custo','/dashboard/cadastros/produtos/importar','Migrar estoque','Custo','O custo médio unitário informado (opcional).','Grava como preço de custo médio do produto, com origem "importação".','R$ 4,50','Informar preço de venda nesta coluna — aqui é o custo.','gestao_empresarial',150,'publicado'),
 ('cadastros.produtos.importar.col_mensagens','/dashboard/cadastros/produtos/importar','Migrar estoque','Mensagens','Avisos e erros detectados na linha (tipo SPED, origem, NCM, código repetido…).','Diz exatamente o que corrigir na planilha para a linha passar.','Sem NCM (item tributável) — recomendado','Reimportar sem corrigir o que a mensagem aponta.','gestao_empresarial',160,'publicado'),
 ('cadastros.produtos.importar.carregar','/dashboard/cadastros/produtos/importar','Migrar estoque','Carregar','Grava os produtos e ajusta os saldos conforme a prévia.','Efetiva a migração; reimportar o mesmo arquivo não duplica (saldo que já bate não gera movimentação).','Carregar','Carregar com erros pendentes sem marcar "só as válidas" — o botão fica bloqueado até resolver.','gestao_empresarial',170,'publicado')
